compose:
ctx => {
  const f = ctx.steps.facts.value;
  const pct = n => Number.isFinite(n) ? n.toFixed(1)+'%' : 'unavailable';
  const line = s => '• '+s;
  const up = f.targets.filter(t => t.status === 'up').length;
  const attention = [];
  if (f.stale || f.quality !== 'good') attention.push('Snapshot '+(f.stale?'stale':'quality: '+f.quality)+' — '+f.snapshotAgeSeconds+'s old');
  for (const t of f.targets.filter(t => t.status !== 'up')) attention.push(t.name+': '+t.status);
  for (const d of f.disks) {
    if (!Number.isFinite(d.free)) attention.push(d.mount+': free space unavailable');
    else if (d.free < 10) attention.push(d.mount+': '+pct(d.free)+' free (below 10%)');
  }
  for (const [label,value] of [['CPU',f.cpuPercent],['Memory',f.memoryPercent]]) {
    if (!Number.isFinite(value)) attention.push(label+': unavailable');
    else if (value >= 90) attention.push(label+': '+pct(value)+' (at least 90%)');
  }
  const reduced=f.availability24h.filter(x => Number.isFinite(x.percent) && x.percent<99);
  for (const t of reduced) attention.push(t.job+': '+t.percent.toFixed(2)+'% scrape availability over 24h');
  if (!f.availability24h.length) attention.push('24h scrape availability unavailable');
  for (const t of f.availability24h.filter(x=>!Number.isFinite(x.percent))) attention.push(t.job+': 24h availability unavailable');
  for (const warning of f.warnings || []) attention.push('Prometheus: '+warning);
  const sections=[
    {title:'🔎 ATTENTION',text:attention.length?attention.map(line).join('\n'):'• No threshold breaches in these measurements.'},
    {title:'🖥 HOST',text:line('CPU: '+pct(f.cpuPercent))+'\n'+line('Memory: '+pct(f.memoryPercent))},
    {title:'💾 DISK FREE',text:f.disks.map(d=>line(d.mount+': '+pct(d.free))).join('\n')},
    {title:'📡 SERVICES',text:line(up+'/'+f.targets.length+' scrape targets reachable now')+'\n'+line('24h: '+reduced.length+' targets below 99% scrape availability')},
  ];
  let note=ctx.steps.analysis.status==='succeeded'?ctx.steps.analysis.value.summary.replace(/\s+/g,' ').trim():'AI summary unavailable; measurements are shown above.';
  if (note.length>260) note=note.slice(0,257).replace(/\s+\S*$/,'')+'…';
  sections.push({title:'💬 INTERPRETATION',text:note});
  sections.push({title:'ℹ DATA',text:'Snapshot '+f.snapshotAgeSeconds+'s old · '+f.quality+'\nScrape reachability only; application events and Talìa alerts are not covered.'});
  return {subject:'Talìa · Homelab report',summary:attention.length?'⚠ Items need attention':'✓ No issue flagged by these checks',sections};
}

